import{_ as e,b as o,f as t,I as r}from"./chunks/framework.DYvp_Vyw.js";const u=JSON.parse('{"title":"Matlab学习笔记006 - 数据处理方法与多项式","description":"","frontmatter":{"title":"Matlab学习笔记006 - 数据处理方法与多项式","date":"2025-05-06T13:16:20.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-006.md","filePath":"posts/Matlab-Own-Study-006.md"}'),d={name:"posts/Matlab-Own-Study-006.md"};function h(l,a,n,c,i,s){return t(),o("div",null,a[0]||(a[0]=[r('<p>自己学习后整理的笔记（实时更新）</p><hr><h1 id="一、-基本统计处理" tabindex="-1">一、 基本统计处理 <a class="header-anchor" href="#一、-基本统计处理" aria-label="Permalink to &quot;一、  基本统计处理&quot;">​</a></h1><h2 id="_1、查取最大值" tabindex="-1">1、查取最大值 <a class="header-anchor" href="#_1、查取最大值" aria-label="Permalink to &quot;1、查取最大值&quot;">​</a></h2><p>MAX函数的命令格式有： <code>[Y,I]= max (X)</code>：将max(X)返回矩阵X的各列中的最大元素值及其该元素的位置赋予行向量Y与I；当X为向量时，则Y与I为单变量。 <code>[Y,I]=max(X,[],DIM)</code>：按数组X的第DIM维的方向查取其最大的元素值及其该元素的位置赋予向量Y与I。</p><h2 id="_2、查取最小值" tabindex="-1">2、查取最小值 <a class="header-anchor" href="#_2、查取最小值" aria-label="Permalink to &quot;2、查取最小值&quot;">​</a></h2><p>MIN函数用来查取数据序列的最小值。它的用法与命令格式与MAX函数完全一样，所不同的是执行的结果是最小值。</p><h2 id="_3、求中值" tabindex="-1">3、求中值 <a class="header-anchor" href="#_3、求中值" aria-label="Permalink to &quot;3、求中值&quot;">​</a></h2><p>所谓中值，是指在数据序列中其值的大小恰好在中间。例如，数据序列9,-2,5,7,12的中值为7 。 如果为偶数个时，则中值等于中间的两项之平均值。 MEDIAN函数调用的命令格式有： <code>Y=median(X)</code>：将<code>median(X)</code>返回矩阵X各列元素的中值赋予行向量Y。若X为向量，则Y为单变量。</p><p><code>Y=median(X,DIM)</code>：按数组X的第DIM维方向的元素求其中值赋予向量Y。若DIM=1，为按列操作；若DIM=2，为按行操作。若X为二维数组，Y为一个向量；若X为一维数组，则Y为单变量。</p><h2 id="_4、求和" tabindex="-1">4、求和 <a class="header-anchor" href="#_4、求和" aria-label="Permalink to &quot;4、求和&quot;">​</a></h2><p>命令格式有： <code>Y=sum(X)</code>：将sum(X)返回矩阵X各列元素之和赋予行向量Y；若X为向量，则Y为单变量。</p><p><code>Y=sum(X,DIM)</code>：按数组X的第DIM维的方向的元素求其和赋予Y。若DIM=1，为按列操作；若DIM=2，为按行操作。若X为二维数组，Y为一个向量；若X为一维数组，则Y为单变量。</p><h2 id="_5、求平均值" tabindex="-1">5、求平均值 <a class="header-anchor" href="#_5、求平均值" aria-label="Permalink to &quot;5、求平均值&quot;">​</a></h2><p>MEAN函数调用的命令格式有： <code>Y= mean(X)</code>：将mean (X)返回矩阵X各列元素之的平均值赋予行向量Y。若X为向量，则Y为单变量。</p><p><code>Y= mean(X,DIM)</code>：按数组X的第DIM维的方向的元素求其平均值赋予向量Y。若DIM=1，为按列操作；若DIM=2，为按行操作。若X为二维数组，Y为一个向量；若X为一维数组，则Y为单变量。</p><h2 id="_6、求积" tabindex="-1">6、求积 <a class="header-anchor" href="#_6、求积" aria-label="Permalink to &quot;6、求积&quot;">​</a></h2><p>命令格式有： <code>Y= prod(X)</code>：将prod(X)返回矩阵X各列元素之积赋予行向量Y。若X为向量，则Y为单变量。</p><p><code>Y= prod(X,DIM)</code>：按数组X的第DIM维的方向的元素求其积赋予向量Y。若DIM=1，为按列操作；若DIM=2，为按行操作。若X为二维数组，Y为一个向量；若X为一维数组，则Y为单变量。</p><h2 id="_7、-求累计和、累积积、标准方差与升序排序" tabindex="-1">7、 求累计和、累积积、标准方差与升序排序 <a class="header-anchor" href="#_7、-求累计和、累积积、标准方差与升序排序" aria-label="Permalink to &quot;7、 求累计和、累积积、标准方差与升序排序&quot;">​</a></h2><p>MATLAB提供的求累计和、累积积、标准方差与升序排序等函数分别为<code>CUMSUM、CUMPROD、STD和SORT</code>，这里仅STD函数为MATLAB程序，其余均为内部函数。 这些函数调用的参数与操作方式都与上小节的MEDIAN（中值）函数基本上一样，因此不作详细的介绍。</p><h1 id="二、-多项式运算及其求根" tabindex="-1">二、 多项式运算及其求根 <a class="header-anchor" href="#二、-多项式运算及其求根" aria-label="Permalink to &quot;二、 多项式运算及其求根&quot;">​</a></h1><p>鉴于MATLAB无零下标，故把多项式的一般形式表达为：</p><p>a<sub>1</sub>x<sup>n</sup> + a<sup>2</sup>x<sup>n-1</sup>+···+a<sub>n</sub>x+a<sub>n-1</sub></p><h2 id="_1-多项式求根" tabindex="-1">1. 多项式求根 <a class="header-anchor" href="#_1-多项式求根" aria-label="Permalink to &quot;1.  多项式求根&quot;">​</a></h2><p>命令格式：x=roots(A)。这里A为多项式的系数A(1),A(2),…,A(N),A(N+1)；解得的根赋值给数组X，即X(1),X(2), …,X(N)。</p><h2 id="_2-多项式的建立" tabindex="-1">2. 多项式的建立 <a class="header-anchor" href="#_2-多项式的建立" aria-label="Permalink to &quot;2.  多项式的建立&quot;">​</a></h2><p>若已知多项式的全部根，则可以用POLY函数建立起该多项式；也可以用POLY函数求矩阵的特征多项式。POLY函数是一个MATLAB程序，调用它的命令格式是： <code>A=poly(x)</code> 若x为具有N个元素的向量，则poly(x)建立以x为其根的多项式，且将该多项式的系数赋值给向量A。在此种情况下，POLY与ROOTS互为逆函数；若x为N×N的矩阵x，则poly(x)返回一个向量赋值给A，该向量的元素为矩阵x的特征多项式之系数：A(1),A(2),…,A(N),A(N+1)。</p><h2 id="_3-求多项式的值" tabindex="-1">3. 求多项式的值 <a class="header-anchor" href="#_3-求多项式的值" aria-label="Permalink to &quot;3.  求多项式的值&quot;">​</a></h2><p>POLYVAL函数用来求代数多项式的值，调用的命令格式为： <code>Y=polyval(A,x)</code></p><p>本命令将POLYVAL函数返回的多项式的值赋值给Y。若x为一数值，则Y也为一数值；若x为向量或矩阵，则对向量或矩阵中的每个元素求其多项式的值。</p><h2 id="_4-多项式的四则运算" tabindex="-1">4. 多项式的四则运算 <a class="header-anchor" href="#_4-多项式的四则运算" aria-label="Permalink to &quot;4.  多项式的四则运算&quot;">​</a></h2><h3 id="_1-多项式加、减" tabindex="-1">(1)多项式加、减 <a class="header-anchor" href="#_1-多项式加、减" aria-label="Permalink to &quot;(1)多项式加、减&quot;">​</a></h3><p>对于次数相同的若干个多项式，可直接对多项式系数向量进行加、减的运算。如果多项式的次数不同，则应该把低次的多项式系数不足的高次项用零补足，使同式中的各多项式具有相同的次数。</p><h3 id="_2-多项式乘法" tabindex="-1">(2)多项式乘法 <a class="header-anchor" href="#_2-多项式乘法" aria-label="Permalink to &quot;(2)多项式乘法&quot;">​</a></h3><p>若A、B是由多项式系数组成的向量，则CONV函数将返回这两个多项式的乘积。调用它的命令格式为： <code>C=conv(A,B)</code> 命令的结果C为一个向量，由它构成一个多项式。</p><h3 id="_3-多项式除法" tabindex="-1">(3)多项式除法 <a class="header-anchor" href="#_3-多项式除法" aria-label="Permalink to &quot;(3)多项式除法&quot;">​</a></h3><p>当A、B是由多项式系数组成的向量时，DECONV函数用来对两个多项式作除法运算。调用的命令格式为： <code>[Q,r]=deconv(A,B)</code> 本命令的结果：多项式A除以多项式B获商多项式赋予Q（也为多项式系数向量）；获余项多项式赋予r（其系数向量的长度与被除多项式相同，通常高次项的系数为0）。 DECONV是CONV的逆函数，即有<code>A=conv(B,Q)+r</code>。</p><hr>',39)]))}const _=e(d,[["render",h]]);export{u as __pageData,_ as default};
